'''def _derivatives(cap, bias, slots, rows, rho, mode):
    """Verifier-style derivatives and loads recomputed from reported amounts."""
    E = int(cap.size)
    live = cap > 0.0
    admit = (mode == 'admit')
    L = np.zeros(E)
    for i in range(len(slots)):
        for p, path in enumerate(slots[i]):
            if path is None:
                continue
            x = rows[i][p]
            if x == 0.0:
                continue
            for e in path:
                L[e] += x
    der = {}
    for i in range(len(slots)):
        if demand[i] <= 0.0:
            continue
        for p, path in enumerate(slots[i]):
            if path is None:
                continue
            ok = True
            for e in path:
                if not live[e]:
                    ok = False
                    break
            if not ok:
                continue
            q = 0.0
            for e in path:
                q += (L[e] / cap[e] - bias[e]) / cap[e]
            der[(i, p)] = rows[i][p] + rho * q - (1.0 if admit else 0.0)
    return L, der


def _tune_potentials(cap, demand, slots, mode, rho, bias, rows, pot):
    """Lift potentials by a few ulps so every derivative condition clears zero.

    The nudge is only kept when it strictly improves the certificate ratio, so
    it can never trade a derivative violation for a larger objective gap.
    """
    _L, der = _derivatives(cap, bias, slots, rows, rho, mode)
    lift = {}
    for (i, _p), gv in der.items():
        val = gv + pot[i]
        if val < 0.0:
            lift[i] = max(lift.get(i, 0.0), -val)
    if not lift:
        return rows, pot
    scale = max(1.0, max(abs(v) for v in pot))
    out = list(pot)
    for i, need in lift.items():
        out[i] = out[i] + need + 4.0 * np.finfo(float).eps * scale
    return rows, out


def _emit(cap, demand, slots, mode, rho, bias, rows, pot, gids):''')
# apply the tuning to the winning candidate
